import base64
import tkinter as tk
from io import BytesIO
from PIL import Image

FAVICON_B64 = """

"""

HEADER_B64 = """

"""


def load_favicon(root):
    """Load icons from embedded base64 PNGs. Returns (window_icon, header_icon)."""
    try:
        favicon_window = tk.PhotoImage(data=base64.b64decode(FAVICON_B64))
        root.iconphoto(True, favicon_window)

        favicon_header = tk.PhotoImage(data=base64.b64decode(HEADER_B64))

        return favicon_window, favicon_header
    except Exception:
        return None, None


